"""Security helpers.

At-rest encryption for stored provider API keys using Fernet (cryptography).
Secrets are never logged and never returned in plaintext by default.
"""

from __future__ import annotations

import base64
import hashlib
import logging
import secrets
from typing import Optional

from cryptography.fernet import Fernet, InvalidToken

logger = logging.getLogger("rosy.security")

_fernet: Optional[Fernet] = None


def _derive_key(raw: str, salt: str) -> bytes:
    digest = hashlib.pbkdf2_hmac(
        "sha256", raw.encode("utf-8"), salt.encode("utf-8"), iterations=200_000
    )
    return base64.urlsafe_b64encode(digest)


def init_encryption(secret: str, salt: str) -> None:
    """Initialise the global encryptor. Call once at startup.

    Provide a stable secret (env: ROSY_ENCRYPTION_KEY) so stored secrets
    survive restarts. If empty, an ephemeral random key is used.
    """
    global _fernet
    if secret:
        _fernet = Fernet(_derive_key(secret, salt))
    else:
        random_key = Fernet.generate_key()
        _fernet = Fernet(random_key)
        logger.warning("No encryption key configured; secrets will not persist across restarts.")


def encrypt(plaintext: str) -> str:
    if _fernet is None:
        raise RuntimeError("Encryption not initialised.")
    token = _fernet.encrypt(plaintext.encode("utf-8"))
    return token.decode("utf-8")


def decrypt(ciphertext: str) -> str:
    if _fernet is None:
        raise RuntimeError("Encryption not initialised.")
    try:
        return _fernet.decrypt(ciphertext.encode("utf-8")).decode("utf-8")
    except InvalidToken as exc:  # pragma: no cover - defensive
        raise ValueError("Could not decrypt stored secret (key changed?).") from exc


def generate_token(bytes_: int = 32) -> str:
    return secrets.token_urlsafe(bytes_)


def redact(value: str, keep: int = 4) -> str:
    """Return a redacted view of a sensitive string (e.g. API key)."""
    if not value:
        return ""
    if len(value) <= keep + 4:
        return "***"
    return value[:keep] + "..." + value[-2:]

"""AI provider abstraction.

A provider is responsible for turning a list of chat messages into a model
response. Different backends (OpenRouter, OpenAI, Gemini, Anthropic, Groq,
Mistral, custom OpenAI-compatible endpoints) implement `Provider`.
"""

from __future__ import annotations

import abc
from dataclasses import dataclass, field
from typing import Any, Optional

import httpx

from rosy.core.errors import (
    ProviderAuthError,
    ProviderRateLimited,
    ProviderUnavailable,
)


@dataclass
class ChatMessage:
    role: str  # system | user | assistant | tool
    content: str
    name: Optional[str] = None
    # Optional structured tool-call arguments passed by the conversation engine.
    tool_calls: Optional[list[dict]] = None


@dataclass
class ChatResult:
    text: str
    provider: str
    model: str
    usage: dict = field(default_factory=dict)
    raw: Optional[dict] = None
    tool_calls: Optional[list[dict]] = None

    @property
    def prompt_tokens(self) -> int:
        return int(self.usage.get("prompt_tokens", 0) or 0)

    @property
    def completion_tokens(self) -> int:
        return int(self.usage.get("completion_tokens", 0) or 0)


@dataclass
class ProviderConfig:
    """Resolved credentials/model for a single chat call."""

    provider: str
    api_key: str
    base_url: str
    model: str
    extra: dict[str, Any] = field(default_factory=dict)


class Provider(abc.ABC):
    """Base class for AI chat providers."""

    name: str = "base"

    def __init__(self, config: ProviderConfig, http: httpx.AsyncClient) -> None:
        self.config = config
        self.http = http

    # -- API contract for providers --

    @abc.abstractmethod
    async def chat(self, messages: list[ChatMessage], **kwargs: Any) -> ChatResult:
        """Send messages and return a ChatResult."""
        raise NotImplementedError

    @staticmethod
    def _raise_for_status(resp: httpx.Response, provider: str) -> None:
        if resp.status_code == 429:
            raise ProviderRateLimited(f"{provider} rate limited (HTTP 429)", provider=provider)
        if resp.status_code in (401, 403):
            raise ProviderAuthError(f"{provider} rejected the API key", provider=provider)
        if resp.status_code >= 500:
            raise ProviderUnavailable(f"{provider} returned HTTP {resp.status_code}", provider=provider)
        resp.raise_for_status()

    async def _post_json(self, url: str, payload: dict[str, Any], headers: dict[str, str]) -> dict:
        try:
            resp = await self.http.post(url, json=payload, headers=headers)
        except httpx.TimeoutException as exc:
            raise ProviderUnavailable(f"{self.name} timed out", provider=self.name) from exc
        except httpx.HTTPError as exc:
            raise ProviderUnavailable(f"{self.name} network error", provider=self.name) from exc
        self._suppress_auto_retry(resp)
        self._handle_status(resp)
        return resp.json()

    def _handle_status(self, resp: httpx.Response) -> None:
        self._suppress_auto_retry(resp)
        if resp.status_code == 429:
            raise ProviderRateLimited(f"{self.name} rate limited", provider=self.name)
        if resp.status_code in (401, 403):
            raise ProviderAuthError(f"{self.name} auth error", provider=self.name)
        if resp.status_code >= 500:
            raise ProviderUnavailable(f"{self.name} HTTP {resp.status_code}", provider=self.name)
        resp.raise_for_status()

    def _suppress_auto_retry(self, resp: httpx.Response) -> None:
        # httpx raises on 4xx/5xx; we handle explicitly and also consume body.
        return None


class OpenAICompatProvider(Provider):
    """Generic implementation for OpenAI-compatible chat endpoints.

    Works for OpenRouter, OpenAI, Groq, Mistral and custom endpoints. Gemini
    and Anthropic have native HTTP APIs and get their own subclasses.
    """

    name = "openai-compat"

    def build_headers(self) -> dict[str, str]:
        headers = {"Authorization": f"Bearer {self.config.api_key}"}
        extra = self.config.extra
        if extra.get("referer"):
            headers["HTTP-Referer"] = extra["referer"]
        if extra.get("title"):
            headers["X-Title"] = extra["title"]
        return headers

    def _payload(self, messages: list[ChatMessage], **kwargs: Any) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "model": self.config.model,
            "messages": [
                {"role": m.role, "content": m.content, **({"name": m.name} if m.name else {})}
                for m in messages
            ],
        }
        if kwargs.get("temperature") is not None:
            payload["temperature"] = kwargs["temperature"]
        if kwargs.get("tools"):
            payload["tools"] = kwargs["tools"]
        return payload

    async def chat(self, messages: list[ChatMessage], **kwargs: Any) -> ChatResult:
        payload = self._payload(messages, **kwargs)
        url = self.config.base_url.rstrip("/") + "/chat/completions"
        data = await self._safe_json(url, payload, self.build_headers())
        try:
            choice = data["choices"][0]
        except (KeyError, IndexError) as exc:
            raise ProviderUnavailable(f"{self.name}: malformed response", provider=self.name) from exc
        message = choice.get("message", {})
        text = message.get("content") or ""
        tool_calls = message.get("tool_calls")
        return ChatResult(
            text=text,
            provider=self.name,
            model=self.config.model,
            usage=data.get("usage", {}),
            raw=data,
            tool_calls=tool_calls,
        )


class ProviderRegistry:
    """Registry mapping provider keys to provider classes."""

    def __init__(self) -> None:
        self._classes: dict[str, type[Provider]] = {
            "openai": OpenAICompatProvider,
            "openrouter": OpenAICompatProvider,
            "groq": OpenAICompatProvider,
            "mistral": OpenAICompatProvider,
        }

    def register(self, name: str, cls: type[Provider]) -> None:
        self._classes[name] = cls

    def create(
        self,
        name: str,
        config: ProviderConfig,
        http: httpx.AsyncClient,
    ) -> Provider:
        cls = self._classes.get(name)
        if cls is None:
            raise ValueError(f"Unknown provider: {name}")
        return cls(config, http)

