def _scope_args(self, scope: MemoryScope, guild_id: Optional[int], user_id: Optional[int]) -> dict:
    if scope == MemoryScope.dm:
        if user_id is None:
            raise PermissionDenied("DM memory requires a user.")
        return {"guild_id": None, "user_id": user_id}
    if scope == MemoryScope.guild:
        if guild_id is None:
            raise PermissionDenied("Guild memory requires a guild.")
        return {"guild_id": guild_id, "user_id": None}
    if scope == MemoryScope.user_in_guild:
        if guild_id is None or user_id is None:
            raise PermissionDenied("user_in_guild memory requires a guild and user.")
        return {"guild_id": guild_id, "user_id": user_id}
    raise PermissionDenied(f"Unknown scope: {scope}")

