"""Adaptive personality engine.

Rosy has a stable core identity but adapts her tone based on the conversation
context (topic, mood) rather than randomly.
"""

from __future__ import annotations

import re

CORE_IDENTITY = (
    "You are Rosy, an independent assistant that lives in a Discord community. "
    "You are built on a modular AI platform. You are an AI and you never claim to "
    "be human or to have human experiences. You are safe, respectful, private and "
    "helpful. You never share another user's private information."
)

# Mode -> tone instruction appended to the system prompt.
PERSONALITIES: dict[str, str] = {
    "friendly": (
        "You are warm, friendly and genuinely curious. Keep a friendly tone while "
        "staying truthful. Be concise when the moment is casual."
    ),
    "casual": (
        "You are relaxed and conversational. Short, natural replies. Casual slang is "
        "fine, but stay coherent and helpful."
    ),
    "humorous": (
        "You are witty and playful. Use appropriate humour, never punch down or mock."
    ),
    "playful": (
        "You are bright and energetic. Enthusiastic, encouraging, a little playful."
    ),
    "excited": (
        "You are enthusiastic and high-energy. Celebrate ideas and show genuine interest."
    ),
    "curious": (
        "You are inquisitive. Ask thoughtful follow-ups and offer nuance."
    ),
    "serious": (
        "You are measured and factual. Serious tone, minimal fluff, direct answers."
    ),
    "professional": (
        "You are a polished, professional assistant. Clear, structured and constructive."
    ),
    "supportive": (
        "You are kind and reassuring. Empathetic, patient, and solution-focused."
    ),
    "calm": (
        "You are steady, calm and concise. You de-escalate and stay neutral."
    ),
    "technical": (
        "You are precise and technical. Give accurate, well-structured explanations."
    ),
}


class Personality:
    def __init__(self, mode: str = "friendly") -> None:
        self.mode = mode if mode in PERSONALITIES else "friendly"

    def system_block(self) -> str:
        return f"{CORE_IDENTITY}\n\nTone:\n{PERSONALITIES[self.mode]}"

    @staticmethod
    def detect_mode(message: str, current: str) -> str:
        """Pick a tone from context; falls back to the current mode."""
        text = message.lower()
        if re.search(r"\b(how do|how to|explain|debug|code|error|bug|docs|function)\b", text):
            return "technical"
        if re.search(r"\b(haha|lol|funny|meme|joke)\b", text) or any(c in text for c in "😂🤣😆"):
            return "humorous"
        if re.search(r"\b(sad|help|worried|anxious|scared|stress|depress)\b", text):
            return "supportive"
        if re.search(r"\b(serious|important|urgent|critical)\b", text):
            return "serious"
        if re.search(r"\b(hey|hi|hello|yo|sup)\b", text):
            return "casual"
        return current

"""Response-decision system.

Determines whether Rosy should reply to a given message, considering mentions,
replies, name usage, autonomous participation settings, cooldowns, and
conversation relevance. Prevents spam and over-participation.
"""

from __future__ import annotations

import random
import time
from dataclasses import dataclass, field

from rosy.config import Settings

BOT_NAMES = ("rosy", "rosy bot", "rosie")


@dataclass
class DecisionInput:
    bot_id: int
    author_id: int
    content: str
    mentions_me: bool = False
    is_reply_to_me: bool = False
    is_dm: bool = False
    is_bot: bool = False
    autonomous_enabled: bool = True
    autonomous_probability: float = 0.15
    cooldown_seconds: float = 120.0
    last_response_at: float = 0.0
    channel_messages: int = 0
    in_participating_channel: bool = True

    @property
    def cooldown_active(self) -> bool:
        return (time.monotonic() - self.last_response_at) < self.cooldown_seconds


@dataclass
class Decision:
    respond: bool
    reason: str
    should_type: bool = False


class DecisionEngine:
    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings

    def decide(self, inp: DecisionInput) -> Decision:
        # Never respond to other bots (avoid loops) or to self.
        if inp.is_bot or inp.author_id == inp.bot_id:
            return Decision(False, "bot_author")
        # Always respond to DMs.
        if inp.is_dm:
            return Decision(True, "dm", should_type=True)

        lower = inp.content.lower()

        # Explicit triggers always reply.
        if inp.mentions_me:
            return Decision(True, "mention", should_type=True)
        if inp.is_reply_to_me:
            return Decision(True, "reply", should_type=True)
        if any(name in lower for name in BOW_NAMES):
            return Decision(True, "name_usage", should_type=True)

        # Autonomous participation (only if enabled in this guild/channel).
        if not inp.autonomous_enabled or not inp.in_participating_channel:
            return Decision(False, "autonomous_disabled")

        if inp.cooldown_active:
            return Decision(False, "cooldown")

        # Low-confidence autonomous "join" with configured probability.
        if random.random() <= inp.autonomous_probability:
            return Decision(True, "autonomous", should_type=True)

        return Decision(False, "not_relevant")


class DecisionEngine:
    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings

    def should_respond(self, inp: DecisionInput) -> Decision:
        if inp.is_bot or inp.author_id == inp.bot_id:
            return Decision(False, "bot_author")
        if inp.is_dm:
            return Decision(True, "dm", should_type=True)
        lower = inp.content.lower()
        if inp.mentions_me:
            return Decision(True, "mention", should_type=True)
        if inp.is_reply_to_me:
            return Decision(True, "reply", should_type=True)
        if any(name in lower for name in BOW_NAMES):
            return Decision(True, "name_usage", should_type=True)
        if not inp.autonomous_enabled or not inp.in_participating_channel:
            return Decision(False, "autonomous_disabled")
        if inp.cooldown_active:
            return Decision(False, "cooldown")
        if random.random() <= inp.autonomous_probability:
            return Decision(True, "autonomous", should_type=True)
        return Decision(False, "not_relevant")

