"""Generic tool framework.

Each tool has a name, description, JSON schema, permission requirements,
execution method, timeout and error handling. Tools are validated before
execution and never grant unrestricted system access.
"""

from __future__ import annotations

import abc
import asyncio
import logging
from dataclasses import dataclass, field
from typing import Any, Callable, Coroutine, Optional

from rosy.core.errors import PermissionDenied, ToolError

logger = logging.getLogger("rosy.tools")


@dataclass
class ToolSpec:
    """A concrete tool definition/registration."""

    name: str
    description: str
    parameters: dict[str, Any]  # JSON-schema-ish
    required_permission: str = "use_tools"  # coarse permission bucket
    timeout_seconds: float = 15.0
    handler: Optional[Callable[..., Any]] = None
    async_handler: Optional[Callable[..., Coroutine[Any, Any, Any]]] = None

    def to_llm_schema(self) -> dict[str, Any]:
        return {
            "type": "function",
            "function": {
                "name": self.name,
                "description": self.description,
                "parameters": {
                    "type": "object",
                    "properties": self.parameters,
                    "required": [],
                },
            },
        }


class BaseTool(abc.ABC):
    """Implement `execute` and expose `spec`."""

    spec: ToolSpec

    @abc.abstractmethod
    async def execute(self, **kwargs: Any) -> Any:
        raise NotImplementedError


class ToolRegistry:
    def __init__(self) -> None:
        self._tools: dict[str, ToolSpec] = {}
        self._handlers: dict[str, Any] = {}

    def register(self, spec: ToolSpec) -> None:
        if spec.name in self._tools:
            raise ToolError(f"Tool already registered: {spec.name}")
        self._tools[spec.name] = spec
        self._handlers[spec.name] = spec.handler or spec.async_handler

    def register_class(self, tool: BaseTool) -> None:
        spec = tool.spec
        spec.async_handler = tool.execute
        self.register(spec)

    def get(self, name: str) -> ToolSpec:
        spec = self._tools.get(name)
        if spec is None:
            raise ToolError(f"Unknown tool: {name}")
        return spec

    def specs(self) -> list[ToolSpec]:
        return list(self._tools.values())

    def llm_schemas(self) -> list[dict[str, Any]]:
        return [t.to_llm_schema() for t in self._tools.values()]

    async def run(self, name: str, arguments: dict[str, Any], *, permission: str = "default_tools") -> str:
        spec = self.get(name)
        if spec.required_permissions and permission not in ("default_tools", spec.required_permissions):
            raise PermissionError(f"Missing permission for tool '{name}'")
        handler = self._handlers.get(name)
        if handler is None:
            raise ToolError(f"Tool '{name}' has no handler.")
        try:
            if asyncio.iscoroutinefunction(handler):
                result = await asyncio.wait_for(handler(**arguments), timeout=spec.timeout_seconds)
            else:
                result = await asyncio.wait_for(
                    asyncio.to_thread(handler, **arguments), timeout=spec.timeout_seconds
                )
        except asyncio.TimeoutError as exc:
            raise ToolError(f"Tool '{name}' timed out.") from exc
        except Exception as exc:
            logger.warning("Tool '%s' failed: %s", name, exc)
            raise ToolError(f"Tool '{name}' failed.") from exc
        return self._stringify(result)

    @staticmethod
    def _stringify(result: Any) -> str:
        if result is None:
            return ""
        if isinstance(result, str):
            return result
        import json

        return json.dumps(result, default=str)

"""Deterministic utility tools: math, conversions, date/time.

Deterministic calculations are done with real code, not left to the LLM to
guess.
"""

from __future__ import annotations

import ast
import datetime
import operator
import time as time_mod

from rosy.tools.base import BaseTool, ToolSpec

ALLOWED_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.BitAnd: operator.and_,
    ast.BitOr: operator.or_,
    ast.BitXor: operator.xor,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
}


class _SafeCalc(ast.NodeVisitor):
    """Evaluate a limited arithmetic AST (numbers + operators only)."""

    def visit_Constant(self, node: ast.Constant) -> float | int:
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError("Only numbers allowed")
    def visit_Name(self, node: ast.Name) -> float:
        raise ValueError(f"Unknown symbol: {node.id}")
    def generic_visit(self, node: ast.AST) -> None:
        raise ValueError(f"Unsupported: {type(node).__name__}")


def safe_eval_math(expression: str) -> str:
    """Evaluate a restricted arithmetic expression safely."""
    tree = ast.parse(expression, mode="eval")

    def visit(node: ast.AST) -> float | int:
        if isinstance(node, ast.Expression):
            return visit(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.BinOp):
            op = ALLOWED_OPS.get(type(node.op))
            if op is None:
                raise ValueError(f"Operator not allowed: {type(node.op).__name__}")
            return op(visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp):
            op = ALLOWED_OPS.get(type(node.op))
            if op is None:
                raise ValueError(f"Unary not allowed: {type(node.op).__name__}")
            return op(visit(node.operand))
        raise ValueError(f"Unsupported syntax: {type(node).__name__}")

    result = visit(tree)
    return result


class MathTool(BaseTool):
    spec = ToolSpec(
        name="math",
        description="Perform a safe arithmetic calculation. Accepts an expression like '2 + 3 * 4'.",
        parameters={
            "expression": {"type": "string", "description": "Arithmetic expression to evaluate."}
        },
    )

    async def execute(self, expression: str = "") -> str:
        if not expression or len(expression) > 200:
            raise ValueError("Invalid expression")
        val = visit_eval(expression)
        return f"{expression} = {val}"


class TimeTool(BaseTool):
    spec = ToolSpec(
        name="current_time",
        description="Get the current UTC date and time.",
        parameters={"timezone": {"type": "string", "description": "Optional IANA timezone, default UTC."}},
    )

    async def execute(self, timezone: str = "UTC", **kwargs) -> str:
        from datetime import datetime, timezone as tz
        from zoneinfo import ZoneInfo

        try:
            zone = ZoneInfo(timezone) if timezone and timezone != "UTC" else tz.utc
        except Exception:
            zone = tz.utc
        now = datetime.now(zone)
        return now.strftime("%Y-%m-%d %H:%M:%S %Z")


def visit_eval(expression: str) -> float | int:
    return safe_eval_math(expression)

"""Web and file/document tools (safe, network-bounded)."""

from __future__ import annotations

import re

import httpx

from rosy.config import Settings
from rosy.tools.base import BaseTool, ToolSpec


class WebFetchTool(BaseTool):
    spec = ToolSpec(
        name="web_fetch",
        description="Fetch and extract the main text of a public web page (markdown-like).",
        parameters={
            "url": {"type": "string", "description": "Absolute http(s) URL."},
            "max_chars": {"type": "integer", "description": "Max characters to return."},
        },
        timeout_seconds=20.0,
    )

    def __init__(self, http: httpx.AsyncClient) -> None:
        self.http = http

    async def execute(self, url: str = "", max_chars: int = 6000, **kwargs) -> str:
        if not re.match(r"^https?://", url):
            raise ValueError("Only http(s) URLs are allowed.")
        try:
            resp = await self.http.get(url, follow_redirects=True)
            resp.raise_for_status()
        except httpx.HTTPError as exc:
            raise ValueError(f"Could not fetch page: {exc}") from exc
        text = _html_to_text(resp.text)
        return text[:max_chars]


class ExtractTextTool(BaseTool):
    """Extract readable text from an uploaded file (text/pdf/plain)."""

    spec = ToolSpec(
        name="extract_text",
        description="Extract readable text from a document (txt/md/csv/pdf).",
        parameters={
            "filename": {"type": "string", "description": "Name of the uploaded file."},
            "max_chars": {"type": "integer", "description": "Max characters to return."},
        },
        timeout_seconds=20.0,
    )

    def __init__(self, file_provider=None) -> None:
        self.files = file_provider

    async def execute(self, filename: str = "", max_chars: int = 8000, **kwargs) -> str:
        if self.files is None:
            raise ValueError("File access not configured.")
        data = await self.files.read(filename)
        if data is None:
            raise ValueError("File not found.")
        if isinstance(data, bytes):
            # only plain-text-like content is decoded here.
            try:
                return data.decode("utf-8", errors="replace")[:max_chars]
            except Exception:
                raise ValueError("Binary file; text extraction not supported for this type yet.")
        return str(data)[:max_chars]


def _html_to_text(html: str) -> str:
    """Very lightweight HTML->text; strips tags and scripts."""
    text = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", html)
    text = re.sub(r"(?is)<[^>]+>", " ", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


class WebTools:
    """Factory that registers the web/file tools into a registry."""

    @staticmethod
    def register(registry, *, settings: Settings | None = None, http=None, files=None) -> None:
        registry.register_class(WebFetchTool(http=http))
        registry.register_class(ExtractTextTool(files_provider=files))

