"""Reminder commands (timezone-aware, persisted in PostgreSQL)."""

from __future__ import annotations

import re
from datetime import datetime, timedelta, timezone

import discord
from discord import app_commands
from discord.ext import commands

_UNIT_SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400, "w": 604800}


def parse_delta(text: str) -> timedelta | None:
    """Parse strings like '30m', '2h', '1d', '90 seconds'."""
    text = text.strip().lower()
    m = re.match(r"^(\d+)\s*(s|m|h|d|w)?$", text)
    if m:
        num = int(m.group(1))
        unit = m.group(2) or "m"
        return timedelta(seconds=num * _UNITS_SECONDS[unit])
    if text in ("tomorrow", "tomorrow at noon"):
        return timedelta(days=1)
    return None


class Reminders(commands.Cog, name="Reminders"):
    def __init__(self, bot) -> None:
        self.bot = bot

    @app_commands.command(name="remind", description="Set a reminder (e.g. '30m', '2h', 'tomorrow').")
    async def remind(self, interaction: discord.Interaction, duration: str, message: str) -> None:
        delta = parse_delta(duration)
        if delta is None:
            await interaction.response.send_message(
                "I couldn't parse that duration. Use e.g. `30m`, `2h`, `1d`, `tomorrow`.", ephemeral=True
            )
            return
        fire_at = datetime.now(timezone.utc) + delta
        r = await self.bot.reminders.add(
            channel_id=interaction.channel_id,
            user_id=interaction.user.id,
            message=message,
            fire_at=fire_at,
            guild_id=interaction.guild_id,
        )
        await interaction.response.send_message(
            f"✅ Reminder #{r.id} set for <t:{int(fire_at.timestamp())}:R>."
        )

    @app_commands.command(name="reminders", description="List your pending reminders.")
    async def list_reminders(self, interaction: discord.Interaction) -> None:
        rows = await self.bot.reminders.list_for_user(interaction.user.id)
        if not rows:
            await interaction.response.send_message("You have no pending reminders.", ephemeral=True)
            return
        lines = [
            f"`#{r.id}` {r.fire_at:%Y-%m-%d %H:%M} — {r.message[:60]}" for r in rows if not r.fired
        ]
        await interaction.response.send_message(
            embed=discord.Embed(title="Your reminders", description="\n".join(lines) or "none pending"),
            ephemeral=True,
        )

    @app_commands.command(name="cancel_reminder", description="Cancel one of your reminders by id.")
    async def cancel(self, interaction: discord.Interaction, reminder_id: int) -> None:
        ok = await self.bot.reminders.cancel(reminder_id, interaction.user.id)
        await interaction.response.send_message(
            "Reminder cancelled." if ok else "Couldn't find that reminder.", ephemeral=True
        )


async def setup(bot) -> None:
    await bot.add_cog(Reminders(bot))

"""Games & entertainment cog (modular: trivia, 8-ball, dice, guess)."""

from __future__ import annotations

import random

import discord
from discord import app_commands
from discord.ext import commands

TRIVIA = [
    ("What is the capital of France?", "Paris"),
    ("How many planets are in our solar system?", "8"),
    ("What language is Python written in primarily?", "C"),
    ("What does HTTP stand for?", "HyperText Transfer Protocol"),
    ("What is the largest ocean on Earth?", "Pacific"),
]


class Games(commands.Cog, name="Games"):
    def __init__(self, bot) -> None:
        self.bot = bot

    @app_commands.command(name="8ball", description="Ask the magic 8-ball a question.")
    async def eight_ball(self, interaction: discord.Interaction, question: str) -> None:
        answers = [
            "It is certain.", "Without a doubt.", "Yes — definitely.",
            "Most likely.", "Outlook good.", "Reply hazy, try again.",
            "Ask again later.", "Better not tell you now.", "Cannot predict now.",
            "Don't count on it.", "My sources say no.", "Very doubtful.",
        ]
        await interaction.response.send_message(f"🎱 **Q:** {question}\n**A:** {random.choice(answers)}")

    @app_commands.command(name="dice", description="Roll one or more dice (e.g. 2d6).")
    async def dice(self, interaction: discord.Interaction, dice: str = "1d6") -> None:
        try:
            count, sides = dice.lower().split("d")
            count, sides = int(count), int(sides)
            if count < 1 or count > 10 or sides < 2 or sides > 1000:
                raise ValueError
        except ValueError:
            await interaction.response.send_message("Use format like `2d6`.", ephemeral=True)
            return
        rolls = [random.randint(1, sides) for _ in range(count)]
        await interaction.response.send_message(f"🎲 {dice}: {rolls} (total {sum(rolls)})")

    @app_commands.command(name="trivia", description="Answer a random trivia question.")
    async def trivia(self, interaction: discord.Interaction) -> None:
        question, answer = random.choice(TRIVIA)
        self.bot.trivia_answers = getattr(self.bot, "trivia_answers", {})
        self.bot.trivia_answers[interaction.channel_id] = answer.lower()
        await interaction.response.send_message(f"🧠 **Trivia:** {question}\nReply with your answer.")

    @app_commands.command(name="guess", description="Play a quick guessing game (1-100).")
    async def guess(self, interaction: discord.Interaction) -> None:
        number = random.randint(1, 100)
        if not hasattr(self.bot, "guess_games"):
            self.bot.guess_games = {}
        self.bot.guess_games[interaction.channel_id] = number
        await interaction.response.send_message(
            "🎯 I've picked a number between 1 and 100. Reply with `guess <number>` to try!"
        )

    @commands.Cog.listener()
    async def on_message(self, message: discord.Message) -> None:
        if message.author.bot or message.guild is None:
            return
        content = message.content.lower().strip()
        if content.startswith("guess ") and hasattr(self.bot, "guess_games"):
            try:
                num = int(content.split()[1])
            except (IndexError, ValueError):
                return
            target = self.bot.guess_games.get(message.channel.id)
            if target is None:
                return
            if num == target:
                del self.bot.guess_games[message.channel.id]
                await message.reply(f"🎉 Correct! The number was **{num}**.")
            else:
                await message.reply("Too high! 📈" if num > target else "Too low! 📉")
        # trivia answers
        if content and getattr(self.bot, "trivia_answers", {}).get(message.channel.id) == content:
            del self.bot.trivia_answers[message.channel.id]
            await message.reply("✅ Correct! Well done.")


async def setup(bot) -> None:
    await bot.add_cog(Games(bot))

"""Music cog: play audio via yt-dlp + ffmpeg into a voice channel.

Gracefully disabled if yt-dlp/ffmpeg are unavailable (keeps the bot functional
on minimal deployments).
"""

from __future__ import annotations

import asyncio
import logging

import discord
from discord import app_commands
from discord.ext import commands

logger = logging.getLogger("rosy.music")


class Music(commands.Cog, name="Music"):
    def __init__(self, bot) -> None:
        self.bot = bot
        self.queue: dict[int, list[str]] = {}
        self._volume: dict[int, float] = {}
        self._loop: dict[int, bool] = {}
        self._current: dict[int, str] = {}

    def _ytdl_available(self) -> bool:
        try:
            import yt_dlp  # noqa: F401

            return True
        except ImportError:
            return False

    @app_commands.command(name="play", description="Play a song/URL in your voice channel.")
    async def play(self, interaction: discord.Interaction, query: str) -> None:
        if not self._ytdl_available():
            await interaction.response.send_message(
                "Music is not installed on this deployment (missing `yt-dlp`). Chat, games, and tools still work.",
                ephemeral=True,
            )
            return
        author = interaction.user
        if not author.voice or not author.voice.channel:
            await interaction.response.send_message("Join a voice channel first.", ephemeral=True)
            return
        vc = interaction.guild.voice_client
        if vc is None:
            vc = await author.voice.channel.connect()
        self.queue.setdefault(interaction.guild_id, []).append(query)
        await interaction.response.send_message(f"🔎 Added **{query}** to the queue.")
        if not vc.is_playing():
            await self._play_next(interaction.guild_id, interaction.channel)

    async def _play_next(self, guild_id: int, channel) -> None:
        vc = self.bot.get_guild(guild_id).voice_client
        if vc is None or not self.queue.get(guild_id):
            return
        query = self.queue[guild_id].pop(0)
        self._current[guild_id] = query
        url = await self._resolve_url(query)
        if url is None:
            await channel.send("Couldn't find that track.")
            await self._play_next(guild_id, channel)
            return
        vc.play(discord.FFmpegPCMAudio(url, executable=self.bot.settings.ffmpeg_path))
        vc.source = discord.PCMVolumeTransformer(vc.source, volume=self._volume.get(guild_id, 1.0))
        await channel.send(f"▶️ Now playing: **{query}**")

    async def _get_url(self, query: str) -> str | None:
        try:
            import yt_dlp

            opts = {"format": "bestaudio/best", "quiet": True, "noplaylist": True, "youtube_metadata": False}
            with yt_dlp.YoutubeDL(opts) as ydl:
                info = ydl.extract_info(query, download=False)
                return info.get("url")
        except Exception as exc:
            logger.warning("yt-dlp error: %s", exc)
            return None

    @app_commands.command(name="skip", description="Skip the current track.")
    async def skip(self, interaction: discord.Interaction) -> None:
        vc = interaction.guild.voice_client
        if vc and vc.is_playing():
            vc.stop()
            await interaction.response.send_message("⏭ Skipped.")
        else:
            await interaction.response.send_message("Nothing playing.", ephemeral=True)

    @app_commands.command(name="stop", description="Stop playback and clear the queue.")
    async def stop(self, interaction: discord.Interaction) -> None:
        self.queue.pop(interaction.guild_id, None)
        vc = interaction.guild.voice_client
        if vc:
            vc.stop()
        await interaction.response.send_message("🛑 Stopped and cleared queue.")

    @app_commands.command(name="pause", description="Pause playback.")
    async def pause(self, interaction: discord.Interaction) -> None:
        vc = interaction.guild.voice_client
        if vc and vc.is_playing():
            vc.pause()
            await interaction.response.send_message("⏸ Paused.")
        else:
            await interaction.response.send_message("Nothing playing.", ephemeral=True)

    @app_commands.command(name="resume", description="Resume playback.")
    async def resume(self, interaction: discord.Interaction) -> None:
        vc = interaction.guild.voice_client
        if vc and vc.is_paused():
            vc.resume()
            await interaction.response.send_message("▶️ Resumed.")

    @app_commands.command(name="queue", description="Show the current queue.")
    async def queue(self, interaction: discord.Interaction) -> None:
        q = self.queue.get(interaction.guild_id, [])
        if not q:
            await interaction.response.send_message("Queue is empty.", ephemeral=True)
            return
        await interaction.response.send_message("\n".join(f"{i}. {t}" for i, t in enumerate(q, 1))[:1900])


async def setup(bot) -> None:
    await bot.add_cog(Music(bot))

"""Voice cog: join/leave voice, and speak text via a TTS provider (optional)."""

from __future__ import annotations

import logging

import discord
from discord import app_commands
from discord.ext import commands

logger = logging.getLogger("rosy.voice")


class Voice(commands.Cog, name="Voice"):
    def __init__(self, bot) -> None:
        self.bot = bot

    @app_commands.command(name="join", description="Make Rosy join your voice channel.")
    async def join(self, interaction: discord.Interaction) -> None:
        author = interaction.user
        if not author.voice or not author.voice.channel:
            await interaction.response.send_message("Join a voice channel first.", ephemeral=True)
            return
        if interaction.guild.voice_client:
            await interaction.guild.voice_client.move_to(author.voice.channel)
        else:
            await author.voice.channel.connect()
        await interaction.response.send_message(f"🔊 Joined {author.voice.channel.name}.")

    @app_commands.command(name="leave", description="Make Rosy leave the voice channel.")
    async def leave(self, interaction: discord.Interaction) -> None:
        vc = interaction.guild.voice_client
        if vc:
            await vc.disconnect()
            await interaction.response.send_message("👋 Left the voice channel.")
        else:
            await interaction.response.send_message("I'm not in a voice channel.", ephemeral=True)

    @commands.Cog.listener()
    async def on_voice_state_update(self, member, before, after) -> None:
        """Auto-leave if Rosy is alone in the channel."""
        if member.id != self.bot.user.id and before.channel is not None and after.channel is None:
            return
        vc = member.guild.voice_client if member.guild else None
        if vc and len(vc.channel.members) <= 1:
            try:
                await vc.disconnect()
            except Exception:
                pass


async def setup(bot) -> None:
    await bot.add_cog(Voice(bot))

"""Plugin framework placeholder.

Future plugins register here. The core already supports per-guild plugin
configuration via the `PluginConfig` table and the `PluginRegistry` pattern
used by tools. Extend without rewriting the core.
"""

from __future__ import annotations

import logging
from typing import Any

logger = logging.getLogger("rosy.plugins")


class Plugin:
    name: str = ""
    description: str = ""

    async def on_load(self, bot) -> None:  # pragma: no cover - extension point
        pass

    async def on_unload(self, bot) -> None:  # pragma: no cover - extension point
        pass


class PluginRegistry:
    def __init__(self) -> None:
        self._plugins: dict[str, Plugin] = {}

    def register(self, plugin: Plugin) -> None:
        self._plugins[plugin.name] = plugin
        logger.info("Registered plugin: %s", plugin.name)

    async def load_all(self, bot) -> None:
        for plugin in self._plugins.values():
            try:
                await plugin.connect(bot)
            except Exception:
                logger.exception("Failed to load plugin %s", plugin.name)


def build_default_registry() -> PluginRegistry:
    return PluginRegistry()

